// era-content.js — narrative content (lede, prose, events) for the era detail view
(function augmentPeriods() {
  if (typeof PERIODS === 'undefined') return;
  const C = {
    "han-tardio": {
      paged: true,
      bgImg: "assets/img/Eras/Era_Han_tardio.webp",
      lede: "El Gran Imperio Han no colapsa de golpe. Se desangra durante décadas de emperadores que mueren jóvenes y dejan el trono a niños gobernados por eunucos y clanes familiares. El Emperador Ling es el símbolo de esta decadencia: vende cargos oficiales al mejor postor, enriquece a los Diez Eunucos y desatiende las hambrunas que arrasan provincias enteras.",
      prose: [
        "El Han Tardío no colapsa de golpe. Se desangra durante décadas de emperadores que mueren jóvenes y dejan el trono a niños gobernados por eunucos y clanes familiares. El Emperador Ling es el símbolo de esta decadencia: vende cargos oficiales públicamente, enriquece a los Diez Eunucos y desatiende las hambrunas que arrasan provincias enteras.",
        "Figuras como Cao Cao, Liu Bei y Sun Jian dan sus primeros pasos en este escenario. No son aún señores de la guerra: son funcionarios menores, voluntarios o soldados de fortuna que observan cómo el sistema se pudre a su alrededor. La catástrofe está sembrada. Solo falta la chispa.",
      ],
      events: [
        {
          y: "~168 d.C.",
          type: "Crisis política",
          n: "Regencias de los eunucos",
          d: "La muerte prematura del Emperador Huan deja el trono a un niño. Los Diez Eunucos y los clanes familiares luchan por la regencia, vaciando la autoridad imperial de toda sustancia real.",
          body: `<p>El Romance de los Tres Reinos comienza, antes incluso de que aparezca Liu Bei, con una sentencia sobre el destino de los imperios: <em>«Lo que ha estado unido mucho tiempo acabará por dividirse; lo que ha estado dividido mucho tiempo acabará por unirse.»</em> La primera ilustración de esta ley son los Diez Eunucos —los 十常侍, Diez Asistentes Permanentes— que gobiernan en nombre de un Emperador incapaz de gobernar por sí mismo.</p><p>Zhang Rang es el más poderoso de los diez. El Emp. Ling lo llama «padre». Zhao Zhong, Duan Gui, Guo Sheng, Feng Xu, Hou Lan, Jian Shuo, Cheng Kuang, Jian Yi y Song Dian completan el grupo. Juntos controlan los nombramientos, los castigos, el acceso al trono y el flujo de información hacia el Hijo del Cielo. Cualquier oficial que quiera un cargo tiene que pagarles. Cualquier funcionario honesto que los contradiga es denunciado por conspiración y ejecutado.</p><p>Cuando el Emp. Huan muere en 168 d.C., el trono pasa a Liu Hong —doce años, incapaz de reinar solo—, que la historia recordará como el Emp. Ling. Los Dou, familia de la Emperatriz Viuda, intentan recuperar el poder real con el apoyo del general Dou Wu y del gran erudito Chen Fan. Los eunucos responden primero: acusan a ambos de traición, los ejecutan y eliminan a sus aliados. El precedente queda establecido: quien se enfrente a los Diez Eunucos muere.</p>`,
          char: {
            zh: "張讓",
            en: "Zhang Rang",
            fc: "#c9a84c",
            role: "Líder de los Diez Eunucos",
            note: "El más influyente de los eunucos que rodean al Emp. Ling. El Emperador lo llama «padre». Ningún cargo, nombramiento ni decreto pasa sin su aprobación. La corte Han no gobierna: gestiona los intereses de Zhang Rang.",
            href: null,
          },
        },
        {
          y: "168–189 d.C.",
          type: "Gobierno",
          n: "Reinado del Emperador Ling 漢靈帝",
          d: "El Emp. Ling vende cargos imperiales al mejor postor. Su corte se convierte en un mercado donde la lealtad se cotiza en oro y la meritocracia desaparece por completo.",
          body: `<p>La novela describe al Emp. Ling con una economía brutal: amaba <em>«los perros y los caballos, la música y la danza, las joyas y las sedas»</em>. Construyó jardines, reformó el palacio y vistió a sus concubinas con modas de las regiones occidentales. Mientras tanto, vendía los cargos del Estado como si fueran mercancía en un mercado.</p><p>El precio era público y no estaba sujeto a negociación. Un condado costaba diez millones de monedas de cobre. Una prefectura, veinte o treinta millones. Los cargos más altos del Imperio —los Tres Ilustres— también tenían precio. Los funcionarios que compraban sus puestos exprimían después a sus súbditos para recuperar la inversión, trasladando la corrupción de la capital hasta cada aldea del Imperio.</p><p>En este contexto emerge He Jin, cuñado del Emp. Ling y Gran General del Han. He Jin representa al clan familiar que compite con los eunucos por el control de la corte. Su enfrentamiento con Zhang Rang y los Diez Eunucos durará hasta la muerte del Emp. Ling, momento en el que ambas facciones se destruirán mutuamente y abrirán la puerta a Dong Zhuo.</p><p>El contraste que construye Luo Guanzhong es deliberado: mientras la corte acumula lujo y vende cargos, las provincias acumulan hambre y venden tierra. La misma presión fiscal que mantiene el estilo de vida imperial es la que convierte al campesinado en carne de recluta para Zhang Jiao.</p>`,
          char: {
            zh: "何進",
            en: "He Jin",
            fc: "#c9a84c",
            role: "Gran General del Han",
            note: "Cuñado del Emp. Ling y cabeza del clan familiar en la corte. Su enfrentamiento permanente con los eunucos mantiene el poder central en tensión constante. Cuando el Emp. Ling muera, He Jin y los eunucos se destruirán mutuamente y abrirán la puerta a Dong Zhuo.",
            href: "assets/Periods/he-jin.html",
          },
        },
        {
          y: "~175 d.C.",
          type: "Movimiento religioso",
          n: "Predicación de Zhang Jiao 張角",
          d: "El taoísta Zhang Jiao funda el Camino de la Gran Paz y recorre ocho provincias prometiendo curación y justicia. En menos de diez años agrupa a cientos de miles de seguidores desesperados.",
          body: `<p>Zhang Jiao, originario de la commandería de Julu, afirma haber recibido en las montañas un libro sagrado de manos de un anciano divino: el Libro del Camino de la Gran Paz (太平清领书). Con él aprende a sanar enfermedades mediante incantaciones y agua bendita. En un Imperio donde la medicina está reservada a los ricos y las epidemias diezman aldeas enteras, un sanador gratuito que promete justicia acumula seguidores con una velocidad que el gobierno Han no comprende hasta que es demasiado tarde.</p><p>Zhang Jiao organiza a sus seguidores en 36 <em>fangs</em> (方, sectores o células), cada uno con un comandante designado. Los mayores agrupan decenas de miles de hombres; los menores, seis o siete mil. La novela cifra el total en 360.000 hombres dispuestos a activarse simultáneamente. Sus dos hermanos, Zhang Liang y Zhang Bao, dirigen los sectores del norte y del este respectivamente.</p><p>Zhang Jiao se titula a sí mismo «General del Cielo» (天公将军), Zhang Liang «General de la Tierra» (地公将军) y Zhang Bao «General del Hombre» (人公将军), reclamando representar las tres fuerzas del universo. Su lema circula de boca en boca durante años antes del alzamiento: <em>«El Cielo Azul ha muerto; el Cielo Amarillo se alza. En el año Jiazi, la prosperidad llegará a todo lo que hay bajo el cielo.»</em> (苍天已死，黄天当立，岁在甲子，天下大吉).</p><aside class="reader-hist"><strong>Nota histórica</strong>El Camino de la Gran Paz era un movimiento taoísta real con décadas de existencia antes de la rebelión. La novela lo presenta como vehículo de la conspiración de Zhang Jiao desde el principio, mientras que históricamente fue un fenómeno religioso-social que la rebelión instrumentalizó en un momento concreto.</aside>`,
          char: {
            zh: "張角",
            en: "Zhang Jiao",
            fc: "#b87e10",
            role: "Profeta del Camino de la Gran Paz",
            note: "Recorre el Imperio durante una década con un mensaje simple: el Han está podrido, el Cielo Amarillo lo reemplazará. Su red no es una iglesia: es un ejército en espera. Cuando decida activarla, nada podrá detenerla. (También romanizado como Zhang Jue en algunas traducciones.)",
            href: "assets/Periods/zhang-jiao.html",
          },
        },
        {
          y: "180–183 d.C.",
          type: "Crisis social",
          n: "Hambrunas y éxodo campesino",
          d: "Malas cosechas sucesivas y una presión fiscal insostenible expulsan a millones del campo. Los grandes terratenientes concentran tierra mientras el campesinado se radicaliza y mira a Zhang Jiao.",
          body: `<p>La novela abre con una sentencia sobre los imperios y después presenta, como primera figura humana concreta, a Liu Bei en la pobreza. Su bisabuelo era el Príncipe Liu Sheng de Zhongshan —hijo del Emp. Jingdi—, lo que convierte a Liu Bei en descendiente directo de la dinastía Han. Y sin embargo vive en Zhuo con su madre viuda vendiendo sandalias de paja y tejiendo esteras. La sangre imperial más pura del Han agoniza en la miseria más absoluta: no hay mejor resumen del estado del Imperio.</p><p>Frente a su cabaña crece un enorme moral cuya copa se eleva como el dosel de un carruaje imperial —el tipo de vehículo reservado a los príncipes—. De niño, Liu Bei le dijo a sus compañeros de juego que algún día montaría en uno así. Sus tíos lo reprenden por hablar así. Luo Guanzhong planta ese árbol en la primera página para que el lector recuerde la promesa cuando Liu Bei, mucho después, por fin la cumpla.</p><p>Los recaudadores de impuestos llegan a Zhuo. Liu Bei no puede pagar. Su situación es la de millones de campesinos en todo el Imperio: cosechas destruidas por sequías o inundaciones sucesivas, impuestos que no se reducen aunque la cosecha falle, tierras que acaban en manos de los grandes terratenientes cuando el campesino endeudado no puede pagar. Es precisamente ese vacío —hambre, deuda, desesperación— el que Zhang Jiao lleva años llenando con una promesa: no pagar nada, seguirle, y recibir el nuevo cielo que viene.</p>`,
          char: {
            zh: "劉備",
            en: "Liu Bei",
            fc: "#1e8a2e",
            role: "Descendiente Han empobrecido",
            note: "Bisnieto del Emp. Jingdi, vive en la pobreza tejiendo esteras junto a su madre viuda. El mundo que describe esta crisis es el suyo: el de los millones que el Imperio ha dejado atrás. La rebelión que se acerca le dará su primera oportunidad militar.",
            href: "assets/Periods/liu-bei.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Umbral",
          n: "Víspera del Año Jiazi",
          d: "La red de Zhang Jiao planea un alzamiento coordinado en todo el Imperio. Una delación acelera el calendario: el Cielo Amarillo se prepara para sustituir al Cielo Azul. La cuenta atrás ha comenzado.",
          body: `<p>El alzamiento estaba planeado para el primer día del año Jiazi (甲子), el año 60 del ciclo calendárico chino, coincidiendo con el 184 d.C. El número tenía peso simbólico: un ciclo completo cerrándose, el momento perfecto para que el Cielo cambiara su Mandato. Zhang Jiao llevaba años preparándolo. Ma Yuanyi (马元义), su operativo en la capital, coordinaba desde dentro de Luoyang con eunucos aliados en el propio palacio imperial.</p><p>Entonces Tang Zhou (唐周), uno de los conjurados, delató el plan a la corte. Ma Yuanyi fue arrestado y descuartizado por carros —车裂, el método de ejecución más brutal del Imperio—. Los eunucos aliados en el interior del palacio fueron interrogados y ejecutados. Zhang Jiao recibió noticia de la traición.</p><p>Le quedaban días, quizá horas, antes de que los ejércitos imperiales llegaran a Julu. Envió mensajeros a caballo en todas direcciones con un único mensaje: el alzamiento comienza ahora. <em>«Atad telas amarillas en vuestra cabeza»</em> era la señal que no podía retirarse una vez enviada. Al amanecer, en ocho provincias simultáneamente, cientos de miles de hombres se ataron telas amarillas y marcharon sobre las sedes administrativas más cercanas.</p><p>La corte respondió nombrando a He Jin comandante supremo. Lu Zhi (卢植) recibió el mando del frente norte. Huangfu Song (皇甫嵩) y Zhu Jun (朱儁) fueron enviados a los focos del centro. En las milicias voluntarias que se formaron en todo el Imperio, tres hombres que todavía no son nadie reciben sus primeras comisiones militares: Cao Cao, Liu Bei y Sun Jian.</p><aside class="reader-hist"><strong>Nota histórica</strong>La Rebelión de los Turbantes Amarillos está documentada con precisión en el Hou Han Shu y el Sanguo Zhi. La delación de Tang Zhou y la captura de Ma Yuanyi son verificables históricamente. La novela amplifica el papel de Liu Bei en la respuesta militar, que históricamente fue menor que el de Huangfu Song o Zhu Jun.</aside>`,
          char: {
            zh: "張角",
            en: "Zhang Jiao",
            fc: "#b87e10",
            role: "Arquitecto del Cielo Amarillo",
            note: "La delación lo obliga a adelantar el levantamiento antes de que la red esté lista. Manda el mensaje a todos sus capitanes: el Año Jiazi empieza ahora. Su proclama resonará en ocho provincias al amanecer: «El Cielo Azul ha muerto. El Cielo Amarillo se alza».",
            href: "assets/Periods/zhang-jiao.html",
          },
        },
      ],
    },
    "turbantes": {
      paged: true,
      bgImg: "assets/img/Eras/Era_Turbantes_amarillos.webp",
      lede: "Zhang Jiao llevaba seis años sembrando promesas de justicia entre los desheredados de China. En 184 d.C. la red se activa simultáneamente en ocho provincias. Medio millón de guerreros con turbantes amarillos proclaman el Año Jiazi. El mayor levantamiento popular que ha visto el Han.",
      prose: [
        "La revuelta fracasa militarmente en meses, pero su impacto es permanente. El Han convoca a todos los señores regionales para aplacar a los Turbantes, y al hacerlo, arma a los mismos hombres que luego lo destruirán. Cao Cao, Liu Bei, Sun Jian: todos labran su primera reputación militar persiguiendo turbantes amarillos.",
        "El Ejército Amarillo de Qingzhou superviviente —cientos de miles con sus familias— es absorbido por Cao Cao. Transforma a los rebeldes en la columna vertebral de su ejército. La llama que quiso derribar el Imperio acaba por forjarlo.",
        "Cinco años después, en 189 d.C., el Emp. Ling moría. El caos que los Turbantes habían prometido —y no habían logrado— estaba a punto de llegar desde dentro del palacio.",
      ],
      events: [
        {
          y: "178–184 d.C.",
          type: "Movimiento político",
          n: "Difusión del Camino de la Gran Paz",
          d: "Zhang Jiao recorre el Imperio durante seis años como sanador. Su red religiosa en ocho provincias y treinta y seis divisiones es, en realidad, el mayor ejército clandestino que ha conocido China.",
          body: `<p>La novela no presenta a Zhang Jiao como un agitador. Lo presenta como un curandero. Encontró en un monte a un anciano de ojos de jade y barba verde que le entregó los tres volúmenes del <em>Taiping Qingling Shu</em> —el Libro de la Gran Paz— con una instrucción: <em>«Usa esto para salvar a la gente»</em>. Zhang Jiao aprendió sus enseñanzas y recorrió el Imperio ofreciendo lo que el Estado nunca había dado: curación gratuita.</p><p>En un Imperio sin medicina pública, el efecto fue inmediato. Los enfermos que sanaban —o creían sanar— difundían su nombre. El movimiento creció durante seis años hasta cubrir ocho provincias con una red de treinta y seis <em>fangs</em> (方), cada una con su mando militar. Las fangs grandes tenían más de diez mil hombres; las pequeñas, varios miles. Zhang Jiao las controlaba todas desde el centro.</p><p>La estructura era perfecta: si las autoridades preguntaban, era una iglesia. Si miraban hacia otro lado, era un ejército. Zhang Jiao se proclamó «Gran General del Cielo» (天公将军). Su hermano Zhang Liang asumió el título de «Gran General de la Tierra» (地公将军). Zhang Bao, el menor, «Gran General del Hombre» (人公将军). Juntos, los tres hermanos controlaban el mayor movimiento organizado que había visto el Han Tardío. Y nadie en Luoyang lo había visto venir.</p>`,
          char: {
            zh: "张角",
            en: "Zhang Jiao",
            fc: "#b87e10",
            role: "Gran General del Cielo Amarillo",
            note: "Curandero, profeta y organizador militar. Seis años de trabajo clandestino le dan una red en ocho provincias que puede activarse simultáneamente. La novela le concede grandeza genuina: el Imperio no cayó porque fuera débil, sino porque Zhang Jiao lo vio antes que nadie.",
            href: "assets/Periods/zhang-jiao.html",
          },
        },
        {
          y: "Inicio de 184",
          type: "Proclamación",
          n: "El Año Jiazi 甲子",
          d: "La delación de Tang Zhou obliga a Zhang Jiao a activar la red antes de tiempo. Al amanecer, cientos de miles de hombres se atan telas amarillas y marchan. El lema resuena en ocho provincias: «El Cielo Azul ha muerto. El Cielo Amarillo se alza».",
          body: `<p>El alzamiento estaba planeado con precisión calendárica. El primer día del año Jiazi (甲子) —184 d.C., el año 60 del ciclo sexagesimal, un momento de cierre y apertura cósmica— sería el instante en que el «Cielo Amarillo» sustituiría al «Cielo Azul» del Han. La señal estaba preparada, los comandantes instruidos, las fangs listas. Faltaban días.</p><p>Tang Zhou (唐周), uno de los conjurados en la capital, delató el plan a la corte. Ma Yuanyi (马元义), el operativo de Zhang Jiao en Luoyang, fue arrestado y ejecutado por descuartizamiento. Los eunucos aliados dentro del palacio fueron interrogados y eliminados. Zhang Jiao recibió la noticia: la ventana se cerraba. Envió mensajeros a caballo en todas direcciones con una sola orden: el alzamiento comienza ahora.</p><p>El lema era simple e imborrable: <em>苍天已死，黄天当立 — El Cielo Azul ha muerto; el Cielo Amarillo se alza.</em> Al amanecer siguiente, en ocho provincias a la vez, cientos de miles de hombres se ataron telas amarillas en la cabeza y marcharon sobre las sedes administrativas más cercanas. La corte de Luoyang, que nunca había visto nada igual, nombró a He Jin comandante supremo y abrió el reclutamiento en todo el Imperio. En Zhuo, Liu Bei leyó el edicto y suspiró.</p><aside class="reader-hist"><strong>Nota histórica</strong>El alzamiento simultáneo en ocho provincias está documentado en el Hou Han Shu. Los historiadores modernos estiman entre 300.000 y 500.000 combatientes en el pico de la rebelión. La novela amplifica el papel de los protagonistas en la respuesta militar, pero no exagera la magnitud del levantamiento.</aside>`,
          char: {
            zh: "张角",
            en: "Zhang Jiao",
            fc: "#b87e10",
            role: "Gran General del Cielo Amarillo",
            note: "La delación lo obliga a quemar seis años de planificación en una noche. Manda el mensaje a todos sus capitanes: el Año Jiazi empieza hoy. Su proclama resonará en ocho provincias al amanecer. Es el acto más audaz del Romance, y también el último que controla.",
            href: "assets/Periods/zhang-jiao.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Juramento fundacional",
          n: "Juramento del Melocotonero 桃園結義",
          bgImg: "assets/img/Eras/Era_Turbantes_amarillos_treshermanos.webp",
          d: "Liu Bei lee el edicto de reclutamiento y suspira. Detrás de él, un hombre enorme lo interpela. Más tarde, en la huerta de Zhang Fei, tres hombres que acaban de conocerse juran hermandad para siempre.",
          body: `<p>En Zhuo, Liu Bei lee el edicto de reclutamiento del gobernador Liu Yan y suspira. Un hombre enorme —cabeza de leopardo, ojos redondos, mandíbula de golondrina, barba de tigre— aparece detrás de él y lo interpela: <em>«Hombre grande, ¿por qué suspirar si no actúas?»</em> Es Zhang Fei, propietario de tierras. Invita a Liu Bei a beber. En la taberna se cruzan con otro viajero que también se dirige a alistarse: Guan Yu, barba roja y espada al hombro, huyendo de su provincia natal desde que mató a un tirano local. Los tres beben juntos y al día siguiente van a la huerta de melocotoneros de Zhang Fei.</p><p>El juramento que pronuncian bajo los árboles en flor define el resto de la novela: <em>«Nosotros tres, aunque de apellidos distintos, juramos ser hermanos. Trabajaremos juntos para sostener el Han y proteger al pueblo. No pudiendo nacer el mismo día del mismo mes del mismo año, deseamos morir el mismo día del mismo mes del mismo año.»</em> Son tres hombres completamente distintos: Liu Bei lleva sangre imperial pero ningún poder; Guan Yu lleva un código de honor que ninguna lealtad política puede superar; Zhang Fei lleva una fuerza bruta que solo la amistad puede disciplinar.</p><p>El juramento del melocotonero no es histórico —no aparece en el Sanguo Zhi ni en el Hou Han Shu— pero es quizá el momento más famoso de toda la literatura china. Luo Guanzhong lo inventó, o lo amplificó de la tradición oral, porque entendió que esta historia necesitaba un origen moral, no solo militar. Los Tres Reinos no son solo una guerra: son la historia de tres hombres que prometieron algo y pagaron su precio.</p>`,
          char: {
            zh: "关羽",
            en: "Guan Yu",
            fc: "#1e8a2e",
            role: "El Señor de la Guerra Sagrada",
            note: "Se presenta ante Liu Bei y Zhang Fei como un fugitivo que mató a un tirano local y lleva años huyendo. Su primera acción en la novela es unirse a un juramento. La lealtad que pronuncia bajo el melocotonero no la romperá nunca —ni siquiera cuando le cueste la vida.",
            href: "assets/Periods/guan-yu.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Primera campaña",
          n: "Liu Bei, soldado",
          d: "Tras el juramento, Liu Bei y sus hermanos se alistan bajo Lu Zhi —el maestro de Liu Bei— en el frente norte. Pelean bien. El Imperio los usa y no los recompensa.",
          body: `<p>Liu Bei tenía un maestro: Lu Zhi (卢植), uno de los grandes eruditos del Han, el mismo hombre que ahora manda el ejército imperial en el norte contra Zhang Jiao en Guangzong. No es casualidad que Liu Bei elija ese frente para alistarse. Los tres hermanos combaten bajo su antiguo maestro, y combaten bien: Liu Bei llega a rescatar en un momento crítico al general Dong Zhuo —futuro tirano del Imperio— cuando este se ve cercado. La novela planta la ironía sin subrayarla: el hombre que defenderá el Han salva aquí al hombre que luego lo destruirá.</p><p>Al final de las campañas, Liu Bei recibe el nombramiento de magistrado de Anxi (安喜县尉). Es un cargo de tercera categoría en una prefectura menor. Lleva meses de combate, décadas de sangre imperial y una promesa solemne bajo un melocotonero. La burocracia del Han le da un puesto de policía de condado. Cuando un inspector imperial llega a revisar la administración local, Zhang Fei lo ata a un poste y le propina cincuenta latigazos. Liu Bei cuelga su sello en la puerta y los tres abandonan el cargo.</p><p>La escena es cómica en la superficie y brutal en el fondo. Liu Bei tiene las cualidades de un gobernante —y el Imperio no tiene ningún mecanismo para reconocerlo. Pasará años en este limbo: demasiado noble para corromperse, demasiado débil para imponerse, demasiado obstinado para rendirse. Cada señor que lo acoja lo usará. Ninguno lo respetará del todo. Hasta que encuentre a Zhuge Liang, Liu Bei no tendrá ni una estrategia ni una base propia.</p>`,
          char: {
            zh: "刘备",
            en: "Liu Bei",
            fc: "#1e8a2e",
            role: "Soldado sin recompensa",
            note: "Combate bajo su maestro Lu Zhi, rescata a Dong Zhuo sin saberlo, y recibe como pago un cargo menor que acaba abandonando. Es la primera de muchas veces que el Imperio lo subestimará. Liu Bei aprenderá a convertir esa subestimación en una ventaja.",
            href: "assets/Periods/liu-bei.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Primera campaña",
          n: "Cao Cao, primer mando",
          d: "Cao Cao recibe su primer mando autónomo y actúa con una eficiencia que los veteranos notan. No es aún el estratega que reunificará el norte: es un joven oficial que comprende el poder mejor que nadie a su alrededor.",
          body: `<p>La novela introduce a Cao Cao antes de los Turbantes mediante una sola frase del gran oficial Qiao Xuan (桥玄): <em>«El mundo pronto estará en caos. Solo un hombre de capacidad extraordinaria podrá restaurar el orden. Ese hombre eres tú.»</em> Es la única presentación que necesita. Cao Cao tiene entonces veintitantos años, es nieto adoptivo del eunuco jefe Cao Teng, y ya sabe exactamente cómo funciona el sistema —porque ha crecido dentro de él.</p><p>Cuando el alzamiento estalla, Cao Cao es nombrado comandante de caballería (骑都尉) y asignado al frente central bajo Huangfu Song. Combate en Yingchuan (颍川). Gana. Es ascendido a prefecto de Dunqiu (顿丘令). Gana allí también —administrativamente: nombra funcionarios competentes, castiga la corrupción, construye la reputación de hombre que hace que las cosas funcionen. El contraste con Liu Bei es exacto: los dos pelean igual de bien, pero el sistema recompensa a Cao Cao porque Cao Cao sabe hablarle al sistema.</p><p>El Cao Cao de los Turbantes no es todavía el señor de la guerra implacable. Es un oficial talentoso que cree, o quiere creer, que el Han puede reformarse desde dentro. Ese Cao Cao —el que intenta arreglarlo— solo desaparece cuando concluye que no se puede arreglar. Esa conclusión tardará años en llegar. Mientras tanto, construye metodicamente lo que necesitará cuando llegue: reputación, red, y la confianza de los hombres correctos.</p>`,
          char: {
            zh: "曹操",
            en: "Cao Cao",
            fc: "#1e5abf",
            role: "Oficial en ascenso",
            note: "Nieto adoptivo del eunuco jefe, conoce el sistema desde dentro. Su primer mando en la campaña contra los Turbantes confirma lo que Qiao Xuan ya vio: capacidad extraordinaria. La pregunta no es si Cao Cao llegará lejos. La pregunta es hasta dónde está dispuesto a llegar.",
            href: "assets/Periods/cao-cao.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Primera campaña",
          n: "Sun Jian, el Tigre de Jiangdong",
          d: "Sun Jian combate en el sur bajo Zhu Jun con una audacia que incomoda a sus superiores. No tiene sangre imperial ni conexiones políticas. Tiene algo más difícil de fabricar: instinto de combate.",
          body: `<p>Sun Jian es el raro entre los futuros señores. Liu Bei tiene sangre imperial. Cao Cao tiene conexiones. Sun Jian tiene una historia: a los diecisiete años vio a un pirata dividir botín en el muelle de Qiantang y, sin armas y sin apoyo, gesticuló como si llamara a compañeros que no existían. El pirata salió a investigar. Sun Jian lo mató. La novela cuenta esta anécdota como presentación de personaje porque lo dice todo: Sun Jian actúa cuando otros calculan.</p><p>Durante los Turbantes, sirve bajo Zhu Jun en el teatro sur, en la campaña sobre Wancheng (宛城). Recluta voluntarios a su costa —algo que Liu Bei también hace, y que Cao Cao no necesita hacer porque ya tiene nombramientos imperiales—. Combate en primera línea con la temeridad que caracterizará a toda su línea: su hijo Sun Ce heredará este impulso; su nieto Sun Quan aprenderá a contenerse justo a tiempo. Sun Jian no aprende a contenerse. No le hace falta: los que lo rodean aprenden a no subestimarle.</p><p>Al terminar los Turbantes, Sun Jian tiene el historial militar más limpio de los tres futuros señores, y la posición política más débil. El sur —Jiangdong— le reconoce. El norte no sabe quién es. Pasará años convirtiendo hazañas en tierra, hasta que encuentre el Sello Imperial en un pozo de Luoyang y cambie para siempre las reglas del juego.</p>`,
          char: {
            zh: "孙坚",
            en: "Sun Jian",
            fc: "#bf2020",
            role: "El Tigre de Jiangdong",
            note: "Combate bajo Zhu Jun en el sur con recursos propios y audacia desmedida. Sin sangre imperial ni red política, construye su reputación acto a acto. Es el más puro guerrero de los futuros señores —y el que menos tiempo tiene para disfrutarlo.",
            href: "assets/Periods/sun-jian.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Campaña imperial",
          n: "Campaña de Huangfu Song",
          d: "Los generales imperiales Huangfu Song y Zhu Jun fragmentan los ejércitos Turbantes en el centro. En las milicias voluntarias que responden al edicto, Cao Cao, Liu Bei y Sun Jian labran sus primeras reputaciones militares.",
          body: `<p>La respuesta imperial fue rápida. Huangfu Song (皇甫嵩) y Zhu Jun (朱儁) asumieron el mando del frente central; Lu Zhi (卢植) marchó al norte, hacia el bastión de Zhang Jiao en Guangzong. El Imperio tenía generales competentes. El problema no era la capacidad militar, sino que para desplegarlos había tenido que armar a cientos de señores regionales que ahora conocían su propia fuerza.</p><p>Huangfu Song demostró en Changshe (长社) por qué era considerado el mejor general de su generación. Cercado por los Turbantes con su ejército en inferioridad numérica, esperó una noche de viento fuerte y ordenó ataques de fuego en todos los frentes a la vez. El campo rebelde ardió y la moral enemiga se quebró. La táctica se repetiría con variaciones en otros frentes. Al final de 184 d.C., los focos principales del centro y del sur habían sido sofocados.</p><p>En estas campañas, tres hombres que todavía no son nadie acumulan sus primeras victorias. Liu Bei, Guan Yu y Zhang Fei combaten bajo distintos comandantes, ganándose condecoraciones menores que la burocracia imperial se encargará de ignorar. Cao Cao recibe su primer mando autónomo y actúa con una eficiencia que los veteranos notan. El Imperio los usa para apagar la rebelión. Cuando la rebelión acabe, ya no podrá prescindir de ellos.</p>`,
          char: {
            zh: "皇甫嵩",
            en: "Huangfu Song",
            fc: "#c9a84c",
            role: "General supremo del Han",
            note: "El militar más eficaz que el Han Tardío tiene. Sofoca los focos centrales de la rebelión en meses con táctica y energía sin igual. La ironía es histórica: sus victorias salvan al Imperio a corto plazo, pero el precio —armar a los señores regionales— lo destruye a largo.",
            href: "assets/Periods/huangfu-song.html",
          },
        },
        {
          y: "184 d.C.",
          type: "Derrota rebelde",
          n: "Caída de los hermanos Zhang",
          d: "Zhang Jiao muere de enfermedad antes de ser capturado. Sus hermanos Zhang Liang y Zhang Bao son derrotados en batalla. El núcleo dirigente de la rebelión desaparece, aunque los focos locales persisten años.",
          body: `<p>Zhang Jiao murió de enfermedad en Guangzong antes de que Huangfu Song pudiera llegar a él. La novela no le concede una muerte dramática: simplemente muere, consumido por la misma enfermedad que había prometido curar en otros. Huangfu Song, al tomar Guangzong, mandó desenterrar su cadáver para decapitarlo y enviar la cabeza a Luoyang. Era el procedimiento estándar cuando el criminal principal moría antes de su captura.</p><p>Zhang Liang fue derrotado y muerto en la batalla de Guangzong. Zhang Bao cayó en Xiaquyang (下曲阳) poco después. Con los tres hermanos muertos, la organización central del movimiento desapareció. Los historiadores calculan que en las campañas de 184 d.C. murieron más de cien mil Turbantes en combate o ejecución. Pero el fuego no se extinguió del todo: focos locales persistieron durante años, y el nombre «Turbante Amarillo» siguió siendo un símbolo de rebelión popular durante décadas.</p><p>El legado más extraño de la rebelión fue lo que hizo Cao Cao con sus restos. Años después, el Ejército Amarillo de Qingzhou —cientos de miles de Turbantes supervivientes con sus familias— se rindió a Cao Cao. En lugar de ejecutarlos, los integró en su ejército. Los hombres que habían querido destruir el Han se convirtieron en la columna vertebral del ejército que eventualmente lo reemplazaría. La llama que Zhang Jiao encendió para quemar el Imperio acabó, de otra manera, forjándolo.</p><aside class="reader-hist"><strong>Nota histórica</strong>La muerte por enfermedad de Zhang Jiao y la exhumación póstuma están verificadas en el Sanguo Zhi. El destino del Ejército de Qingzhou —absorbido por Cao Cao en 192 d.C.— es uno de los hechos más significativos del periodo y apenas mencionado en la novela.</aside>`,
          char: {
            zh: "张梁",
            en: "Zhang Liang",
            fc: "#b87e10",
            role: "Gran General de la Tierra",
            note: "El segundo hermano. Continúa la resistencia en Guangzong tras la muerte de Zhang Jiao y cae en batalla contra Huangfu Song. Su derrota y la de Zhang Bao en 184 d.C. cierran el capítulo del levantamiento organizado, aunque no la historia de los Turbantes.",
            href: "assets/Periods/zhang-liang.html",
          },
        },
      ],
    },
    "dong-zhuo": {
      paged: true,
      bgImg: "assets/img/Eras/Era_Tirania_dongzhuo.webp",
      lede: "El general fronterizo Dong Zhuo marcha sobre Luoyang con sus tropas norteñas, depone al heredero y convierte al Hijo del Cielo en su marioneta. Lo que sigue son tres años de terror, incendio y conspiración que fragmentan para siempre la autoridad Han.",
      prose: [
        "La muerte del Emp. Ling en 189 d.C. abrió el vacío que los Turbantes no habían conseguido crear. El Gran General He Jin, regente del joven Emp. Shao, creyó poder resolver la vieja guerra entre aristócratas y eunucos de un solo golpe: llamó a los señores militares de las provincias para intimidar a la corte. Fue asesinado antes de que llegaran. Los eunucos fueron masacrados poco después. Y Dong Zhuo, el general fronterizo que He Jin había convocado, encontró Luoyang sin dueño.",
        "Su reinado dura tres años, pero sus efectos son permanentes. La quema de Luoyang —capital Han durante dos siglos— y el traslado forzoso a Chang'an destruyen el símbolo del poder imperial. La Gran Coalición de dieciocho señores fracasa por ambición mutua, pero deja a China dividida en feudos que no volverán a unirse bajo el Han.",
      ],
      events: [
        {
          y: "189 d.C.",
          type: "Crisis política",
          n: "Muerte de He Jin y masacre de eunucos",
          d: "El Gran General He Jin es atraído al palacio y asesinado. Yuan Shao responde masacrando a los Diez Eunucos. El poder central queda en un vacío mortal que nadie puede llenar.",
          body: `<p>He Jin, cuñado del Emp. Ling y Gran General del Han, lleva meses tramando la eliminación de los Diez Eunucos. Su plan es simple y letal: invitar a los señores militares de las provincias a marchar sobre Luoyang. La presión de un ejército en las puertas, calcula, forzará a la Emperatriz Viuda a permitir la purga. El consejero Cao Cao le advierte que no necesita ejércitos para ejecutar a una docena de chamberlanes; que invitar a los señores es sembrar una tormenta mayor que el problema que pretende resolver. He Jin no escucha.</p><p>Zhang Rang y los Diez Eunucos se enteran del plan antes de que los ejércitos lleguen. Actúan primero: el Gran General recibe una invitación imperial de la Emperatriz Viuda para acudir al palacio. He Jin entra sin escolta. En el umbral de los aposentos interiores, donde los guerreros no pueden seguirle, los eunucos lo rodean y lo descuartizan. Su cabeza aparece lanzada desde los muros del palacio ante su propio ejército.</p><p>Yuan Shao no espera órdenes. Toma las puertas del palacio y ordena a sus soldados matar a todo hombre sin barba que encuentren —la señal más rápida para distinguir a los eunucos—. En el caos, decenas de cortesanos sin relación alguna con los Diez Eunucos mueren degollados por error. Zhang Rang y los eunucos supervivientes huyen llevando consigo al joven Emp. Shao y al Príncipe de Chenliu hacia el río. Acorralados en la orilla, Zhang Rang hace una última reverencia al niño-Emperador y se arroja al río.</p><p>Cuando los emisarios de Yuan Shao alcanzan la orilla, el poder imperial lleva horas sin dueño. He Jin muerto, los eunucos exterminados, el Emp. Shao deambulando por el barro del río. Es el vacío que Dong Zhuo llevaba semanas esperando cruzar para llenar.</p>`,
          char: {
            zh: "袁紹",
            en: "Yuan Shao",
            fc: "#7a6040",
            role: "Señor del Norte",
            note: "Jefe del clan Yuan, el más prestigioso de las Cuatro Familias del Han. Es quien desencadena la masacre de eunucos cuando He Jin muere. Su decisión de matar a todo hombre sin barba elimina el problema —y toda posibilidad de volver atrás—. Pronto será elegido comandante de la Gran Coalición, aunque su indecisión estratégica lo perderá.",
            href: null,
          },
        },
        {
          y: "189 d.C.",
          type: "Golpe de Estado",
          n: "Dong Zhuo ocupa Luoyang",
          d: "Con sus tropas norteñas, Dong Zhuo ocupa la capital antes de que nadie pueda detenerle. Depone al Emp. Shao y entroniza al niño Liu Xie como Emp. Xian, su marioneta de por vida.",
          body: `<p>Dong Zhuo lleva años en las fronteras del noroeste combatiendo a los Qiang. Es un general de origen humilde que se ha ganado cada rango en el campo de batalla y que desprecia a los aristócratas de la corte con la intensidad que solo tiene quien ha nacido fuera de sus círculos. Cuando la carta de He Jin le llega invitándolo a marchar sobre Luoyang, entiende la oportunidad antes de que He Jin la entienda él mismo.</p><p>Entra en la capital con tres mil jinetes. Encuentra a los dos jóvenes príncipes —Emp. Shao y el Príncipe de Chenliu— en el camino de regreso al palacio tras el desastre del río. La novela describe la escena con precisión: Dong Zhuo se acerca al Emp. Shao y le habla de lo ocurrido. El Emp. Shao, de catorce años, llora y no acierta a responder. El Príncipe de Chenliu, de nueve, le explica con calma lo sucedido y da instrucciones precisas a los presentes. Dong Zhuo observa y decide en ese momento qué hijo del Emp. Ling le será más útil.</p><p>En días depone al Emp. Shao —que será envenenado meses después— y entroniza al Príncipe de Chenliu con el nombre de Emp. Xian. Es el mismo Emp. Xian que reinará de nombre durante treinta años mientras Cao Cao lo usa como fuente de legitimidad. Pero eso está todavía lejos: por ahora es la marioneta de Dong Zhuo, que se nombra a sí mismo Primer Ministro, Duque de Mei y General Supremo en una sola semana.</p><aside class="reader-hist"><strong>Nota histórica</strong>El Sanguo Zhi registra que el Emp. Xian fue entronizado el noveno mes del año Chuping (189 d.C.) y que gobernó de nombre hasta el vigésimo quinto año de Jian'an (220 d.C.), cuando Cao Pi lo forzó a abdicar. Su reinado nominal de 31 años es el más largo de los emperadores Han del periodo.</aside>`,
          char: {
            zh: "董卓",
            en: "Dong Zhuo",
            fc: "#9922cc",
            role: "Primer Ministro y tirano",
            note: "General de frontera convertido en dueño de China. Brutal, inteligente y profundamente despectivo de la clase letrada que lo rodea. Nombra a su hijo adoptivo Lü Bu como guardaespaldas personal —el guerrero más temible del Imperio a su servicio—. Gobernará Luoyang durante un año antes de verse obligado a huir hacia Chang'an.",
            href: null,
          },
        },
        {
          y: "189 d.C.",
          type: "Tentativa",
          n: "Cao Cao intenta asesinar a Dong Zhuo",
          d: "Cao Cao se acerca al tirano con un sable prestado. Al ver que Dong Zhuo no está dormido, convierte el acto en una ofrenda y huye de Luoyang disfrazado de viajero. Su primera leyenda.",
          bgImg: "assets/img/Eras/Era_Tirania_donzhuo_sevenstardagger.webp",
          body: `<p>Wang Yun, el Ministro de la Corte que trama en silencio la caída de Dong Zhuo, organiza un banquete en su residencia. Invita a los pocos funcionarios que quedan en Luoyang con algo de dignidad intacta. Cuando la velada avanza y el vino hace su efecto, Wang Yun rompe a llorar. Los presentes le preguntan la razón. Wang Yun les describe la situación: el Han moribundo, el Emp. Xian cautivo, Dong Zhuo insaciable. Ninguno de los presentes dice nada. Ninguno excepto Cao Cao, que se ríe.</p><p><em>«Llorar no soluciona nada»</em>, dice Cao Cao. Luego pide prestada la espada de Wang Yun —el Sable de los Siete Tesoros, una hoja de valor incalculable— y anuncia que entrará a los aposentos de Dong Zhuo y lo matará. Wang Yun le da la espada sin hacer preguntas. Cao Cao no tiene un plan: tiene una decisión.</p><p>Entra en la residencia de Dong Zhuo bajo pretexto de una visita de cortesía. Encuentra al Primer Ministro recostado con los ojos cerrados; Lü Bu está en la habitación pero sale un momento a buscar algo. Cao Cao desenfunda. En ese instante Dong Zhuo abre los ojos y ve en el espejo lateral a un hombre con una espada sobre él. Cao Cao no parpadea: se arrodilla, presenta la espada con ambas manos y declara que quería ofrecer al Primer Ministro una hoja de valor excepcional. Dong Zhuo acepta la ofrenda. Lü Bu regresa con un caballo —el regalo de turno— y Cao Cao pide permiso para probarlo. Sale al patio, monta y no regresa jamás.</p><p>En su huida hacia el este, Cao Cao pasa por el distrito de Zhongmou. El funcionario local lo reconoce por los carteles de búsqueda y lo detiene. Esa noche, Cao Cao convence al funcionario Chen Gong de que la causa de Dong Zhuo no vale la pena defender. Los dos huyen juntos. La amistad durará poco —Chen Gong terminará sirviéndole a Lü Bu y muriendo frente a Cao Cao—, pero esta noche comparten la misma oscuridad de los caminos.</p>`,
          char: {
            zh: "曹操",
            en: "Cao Cao",
            fc: "#1e5abf",
            role: "Funcionario en fuga",
            note: "En este momento Cao Cao no tiene ejército, territorio ni título. Solo tiene una decisión y una espada prestada. La escena del magnicidio fallido es el primer gran momento de la novela que pertenece exclusivamente a él: la audacia calculada que convierte el fracaso en leyenda.",
            href: "assets/Periods/cao-cao.html",
          },
        },
        {
          y: "190 d.C.",
          type: "Coalición",
          n: "Gran Coalición de los Dieciocho Señores",
          d: "Cao Cao convoca a los señores regionales bajo el estandarte Han. Dieciocho potentados responden. Yuan Shao es elegido comandante general. La coalición avanza —o finge avanzar— hacia Luoyang.",
          body: `<p>Cao Cao huye de Luoyang con el nombre de Dong Zhuo sobre él y sin un soldado a sus espaldas. En Chenliu, su primo Cao Ren y el comerciante Wei Hong le prestan dinero y reclutas. Con cinco mil hombres, Cao Cao emite una proclama: el Han está en manos de un usurpador, todo señor leal debe alzarse. La carta circula por las provincias durante semanas. Dieciocho responden.</p><p>La reunión es uno de los grandes tableau de la novela: Yuan Shao, el clan más prestigioso del Han; Liu Biao, gobernador de Jingzhou; Kong Rong, el erudito confuciano; Sun Jian, el tigre del Sur que será padre de Sun Quan; Liu Bei, Guan Yu y Zhang Fei, que llegan sin más título que el de sus espadas. Yuan Shao es elegido comandante general por aclamación —su apellido lo garantiza—. Los señores ofrecen sacrificios al cielo, se juran lealtad mutua y beben de la misma copa de vino mezclado con sangre.</p><p>La coalición debería ser irresistible. Tiene números, recursos y la legitimidad del estandarte Han. Lo que no tiene es voluntad común. Cada señor calcula su posición futura tanto o más que la victoria presente. Sun Jian avanza y pelea. Los demás acampan, celebran banquetes y debaten estrategia sin mover un pie. Cuando Sun Jian sufre una derrota por falta de suministros —que Yuan Shao retuvo—, el tejido moral de la coalición se rompe antes de llegar a las murallas de Luoyang.</p>`,
          char: {
            zh: "袁紹",
            en: "Yuan Shao",
            fc: "#7a6040",
            role: "Comandante general de la Coalición",
            note: "Elegido por su apellido, no por su capacidad de mando. Su indecisión ante los pasos de Luoyang y su envidia hacia Sun Jian son las grietas que destruyen la coalición desde dentro. El mismo hombre que masacró a los eunucos en un día tardará meses en no avanzar un kilómetro hacia Dong Zhuo.",
            href: null,
          },
        },
        {
          y: "190 d.C.",
          type: "Batalla",
          n: "Hua Xiong, Guan Yu y el vino caliente",
          d: "El general de Dong Zhuo Hua Xiong decapita a los vanguardistas de la coalición uno tras otro. Guan Yu, sin rango ni título, pide permiso para enfrentarse a él. El vino sigue caliente cuando regresa con la cabeza.",
          body: `<p>El primer obstáculo de la coalición es el Paso Si Shui, defendido por el general Hua Xiong. Los señores del norte envían a sus mejores vanguardistas. Hua Xiong los decapita a todos. Pan Feng, Yu She, Zu Mao: sus cabezas llegan al campamento aliado una tras otra mientras los señores debaten qué hacer a continuación. La moral de la coalición, ya frágil por las disputas internas, está a punto de quebrarse.</p><p>En ese momento se levanta un hombre sin cargo ni título propio: Guan Yu, segundo hermano de Liu Bei, que acude a la reunión de generales como simple escolta. Cuando pide permiso para enfrentarse a Hua Xiong, los comandantes lo miran con desprecio. Yuan Shu —hermano menor de Yuan Shao— se burla abiertamente: <em>«Insultáis a nuestros generales proponiendo a un simple arquero.»</em> Cao Cao interviene: <em>«No lo juzguéis por su apariencia. Tiene el aspecto de un tigre y el caminar de un dragón.»</em> Le ofrece a Guan Yu una copa de vino caliente antes de salir.</p><p>Guan Yu declina el vino: <em>«Dejadlo caliente. Volveré enseguida.»</em> El ruido de cascos y gritos dura minutos. Luego silencio. La cabeza de Hua Xiong rueda sobre la mesa de los generales. El vino sigue humeando.</p><aside class="reader-hist"><strong>Nota histórica</strong>Históricamente fue Sun Jian quien derrotó y mató a Hua Xiong durante la campaña de la coalición. La novela transfiere el mérito a Guan Yu para construir su primera gran hazaña individual. Es uno de los reemplazos de gloria más deliberados de Luo Guanzhong.</aside>`,
          char: {
            zh: "關羽",
            en: "Guan Yu",
            fc: "#1e8a2e",
            role: "Segundo hermano de Liu Bei",
            note: "Aparece en la coalición sin título, sin rango, sin más crédito que el de hermano jurado de un aspirante sin tierra. La escena del vino caliente es su primera aparición en solitario y la que establece su identidad definitiva en la novela: el hombre que promete lo imposible y lo cumple antes de que el vino se enfríe.",
            href: null,
          },
        },
        {
          y: "190 d.C.",
          type: "Batalla",
          n: "Lü Bu en el Paso Hu Lao",
          bgImg: "assets/img/Eras/Era_Tirania_dongzhuo_hulao.webp",
          d: "Lü Bu defiende el Paso Hu Lao en solitario y derrota a los generales de la coalición uno a uno. Liu Bei, Guan Yu y Zhang Fei lo combaten juntos. Es el único combate de la era en que los tres hermanos luchan como uno.",
          body: `<p>Dong Zhuo abandona Si Shui y concentra su defensa en el Paso Hu Lao. Para custodiarlo envía a Lü Bu —su hijo adoptivo y guardia personal—, el guerrero más temible del Imperio. Lü Bu aparece en el Paso sobre su caballo Liebre de Pelo Rojo, con la alabarda Cielo-Cortador en la mano y la armadura que lleva su nombre. La novela no escatima en la descripción: es un hombre construido para impresionar antes de golpear.</p><p>Los mejores generales de la coalición salen uno a uno a desafiarle. Fang Yue, Mu Shun, Wang Kuang: ninguno supera los tres intercambios. Gong Du, Zhang Yi: derrotados en segundos. La moral de la coalición se hunde bajo el Paso mientras Lü Bu pasea su caballo con insolencia frente a las líneas aliadas.</p><p>Zhang Fei sale al galope sin pedir permiso. Combate con Lü Bu más de cincuenta intercambios sin que ninguno ceda terreno. Cuando Guan Yu entra para relevar a su hermano, el combate se prolonga otros cincuenta asaltos. Liu Bei desenfunda sus dos espadas y se une. Los tres hermanos rodean a Lü Bu en un triángulo de ataques simultáneos. Es el único momento de la novela en que los tres pelean juntos contra un solo adversario. Lü Bu, por primera vez, se retira.</p><p>La victoria táctica de la coalición en Hu Lao no sirve de nada: Dong Zhuo ya ha decidido abandonar Luoyang. Cuando los aliados entran en la capital, encuentran cenizas.</p>`,
          char: {
            zh: "呂布",
            en: "Lü Bu",
            fc: "#8b1218",
            role: "General supremo de Dong Zhuo",
            note: "Hijo adoptivo de Dong Zhuo y el guerrero más temible del Romance. Ningún general de la coalición puede enfrentarle en solitario. Solo los tres hermanos juntos lo hacen retroceder. Su lealtad, sin embargo, tiene precio: es el mismo hombre que ya mató a su anterior padre adoptivo Ding Yuan para unirse a Dong Zhuo.",
            href: null,
          },
        },
        {
          y: "190 d.C.",
          type: "Saqueo",
          n: "Luoyang en llamas — El traslado a Chang'an",
          d: "Dong Zhuo ordena incendiar la capital Han y forzar a su población entera a marchar hacia Chang'an. La ciudad que había sido corazón del Imperio durante dos siglos queda reducida a cenizas. El símbolo visible del poder Han deja de existir.",
          body: `<p>La coalición de los Dieciocho Señores no puede —o no quiere— entrar en combate real. Sus vanguardias han sufrido ante Hua Xiong y solo los tres hermanos han conseguido hacer retroceder a Lü Bu. Pero Dong Zhuo no huye por miedo: huye por cálculo. Su consejero Li Ru le presenta el argumento con claridad: Luoyang es indefendible frente a dieciocho ejércitos combinados. Chang'an, al oeste, está rodeada de gargantas montañosas que multiplican el valor de cada soldado. Abandonar la capital a tiempo es más sabio que defenderla hasta la derrota.</p><p>Dong Zhuo acepta. La orden llega a la ciudad sin previo aviso. Los soldados norteños recorren las calles con antorchas. Los palacios imperiales, los depósitos de grano, las residencias de los ministros, los mercados: todo arde. Los habitantes reciben la orden de marchar hacia Chang'an. No se permite detenerse a recoger pertenencias. Los que se niegan son ejecutados. Los que no pueden seguir el ritmo son abandonados en el camino.</p><p>El propio Dong Zhuo ordena abrir las tumbas de los emperadores Han para saquear los tesoros funerarios. Lo que el fuego no destruye, los soldados lo roban. Cuando la coalición entra en Luoyang días después, encuentra una extensión de ruinas humeantes donde había vivido medio millón de personas. Yuan Shao contempla las cenizas. No da ninguna orden. Los Dieciocho Señores se dispersan sin haber atacado al enemigo una sola vez.</p><aside class="reader-hist"><strong>Nota histórica</strong>El Sanguo Zhi y el Hou Han Shu confirman la quema de Luoyang y el traslado forzoso a Chang'an en el primer año de la era Chuping (190 d.C.). Las crónicas mencionan que el camino entre ambas capitales quedó cubierto de cadáveres. Chang'an, primera capital Han cuatrocientos años antes, fue el escenario del poder durante los dos años siguientes.</aside>`,
          char: {
            zh: "李儒",
            en: "Li Ru",
            fc: "#9922cc",
            role: "Consejero estratega de Dong Zhuo",
            note: "El arquitecto intelectual de la tiranía. Mientras Dong Zhuo impone el terror por la fuerza, Li Ru le da la forma política: es él quien argumenta la destitución del Emp. Shao, quien diseña su envenenamiento cuando se convierte en un problema, y quien recomienda el abandono y la destrucción de Luoyang. Aparece poco en la novela, pero sus decisiones son algunas de las más determinantes del período.",
            href: null,
          },
        },
        {
          y: "190 d.C.",
          type: "Descubrimiento",
          n: "El Sello del Cielo 傳國玉璽",
          d: "Los soldados de Sun Jian encuentran en un pozo de Luoyang incendiada el Sello Imperial Han. Sun Jian lo oculta. Yuan Shao lo descubre y lo exige. La semilla de la traición dentro de la propia coalición está plantada.",
          body: `<p>Sun Jian es el único señor de la coalición que avanza y pelea sin calcular la retirada. Es el Tigre de Jiangdong —padre de quien será Sun Quan—, y en este momento el único hombre al sur del Yangtzé con ejército real y voluntad de usarlo. Sus tropas son las primeras en entrar en las ruinas de Luoyang mientras los demás señores debaten en sus tiendas.</p><p>En el fondo de un pozo entre los restos de un pabellón imperial, los soldados de Sun Jian encuentran el cuerpo de una cortesana. Cosido en su ropa, un objeto envuelto en seda: el Sello Imperial Han, la 傳國玉璽, la joya de jade labrada que desde el Primer Emperador legitima a quien la porta como soberano del mundo. Sun Jian la recoge, la esconde entre su equipaje y no dice nada.</p><p>Un espía lo ve. Yuan Shao se entera y convoca a Sun Jian a su tienda. Le pregunta directamente si encontró el sello. Sun Jian jura por su vida y por la de sus hijos que no. Yuan Shao sabe que miente y no puede probarlo. La coalición ya está fracturada por la envidia y la inacción; enfrentarse a Sun Jian ahora sería el golpe final. Lo deja marchar.</p><p>Sun Jian se lleva el sello al sur. Meses después muere en una emboscada durante una campaña menor. El sello pasa a su hijo Sun Ce, que lo intercambia con Yuan Shu a cambio de tres mil soldados para reconquistar Jiangdong. Yuan Shu usará el sello para proclamarse Emperador —el mayor error político del período— y lo perderá todo. La maldición del juramento roto alcanza a toda la cadena.</p>`,
          char: {
            zh: "孫堅",
            en: "Sun Jian",
            fc: "#c43c00",
            role: "Señor del Sur, Tigre de Jiangdong",
            note: "El único señor de la coalición que combate sin calcular la retirada. Su hallazgo del Sello Imperial es el momento de mayor peso histórico que tiene en la novela: decide ocultarlo y jurar en falso, lo que lo convierte en el primer gran traidor de la causa Han dentro de la propia coalición de los leales. Muere sin aprovecharlo. Su hijo lo negociará por soldados.",
            href: null,
          },
        },
        {
          y: "190–192 d.C.",
          type: "Conspiración",
          n: "La Estratagema de la Belleza 美人計",
          d: "Wang Yun coloca a Diao Chan entre Dong Zhuo y Lü Bu, sembrando celos irresistibles. Lü Bu asesina a su propio padre adoptivo. El tirano más temido del Imperio muere a manos de su propia guardia.",
          body: `<p>Instalada la corte en Chang'an, Wang Yun lleva meses buscando la grieta en la armadura de Dong Zhuo. La encuentra en la relación entre el tirano y su hijo adoptivo: Lü Bu es el arma más poderosa de Dong Zhuo, pero también un hombre que ya traicionó una vez a un padre —Ding Yuan— por ambición. Wang Yun tiene en su casa a Diao Chan, una sirvienta de extraordinaria belleza que le jura ser capaz de cualquier sacrificio por el bien del Han. Wang Yun diseña un plan que usa el deseo como cuña.</p><p>Primero presenta a Diao Chan a Lü Bu como prometida. Días después la ofrece a Dong Zhuo como concubina. Dong Zhuo la acepta sin saber del compromiso anterior. Cuando Lü Bu se entera, busca a Diao Chan en los aposentos del Primer Ministro. Ella lo recibe entre lágrimas y le habla de la crueldad con que Dong Zhuo la trata, de cómo sufre lejos de él. Lü Bu arde. La distancia entre el deseo y la traición, en este hombre, es mínima.</p><p>El momento decisivo llega en el palacio. Dong Zhuo, irritado por la presencia de Lü Bu cerca de sus aposentos, le arroja una alabarda. Lü Bu esquiva. Wang Yun ve que la fisura es ya irreparable y actúa: llega ante Lü Bu con una lista de los crímenes de Dong Zhuo contra el Han. Lü Bu escucha. Acepta. El día siguiente, cuando Dong Zhuo llega en carruaje al palacio convocado por un edicto falso del Emp. Xian, Lü Bu lo espera en la puerta. Le clava su alabarda antes de que el tirano pueda hablar.</p><p>Luo Guanzhong describe lo que sigue: los habitantes de Chang'an salen a la calle. Bailan. Se ponen flores en el cabello. El hombre que quemó Luoyang ha muerto a manos del único hombre en el Imperio capaz de matarlo, y ese hombre era su propio hijo.</p>`,
          char: {
            zh: "貂蟬",
            en: "Diao Chan",
            fc: "#9922cc",
            role: "La Bella de la Estratagema",
            note: "Una de las Cuatro Grandes Bellezas de la historia china. La novela la construye como agente consciente de su misión, no como víctima pasiva: jura ante el altar de la luna que actuará para salvar al Han y cumple su promesa con una precisión que ningún general de la coalición fue capaz de alcanzar. Desaparece de la narración tras la muerte de Dong Zhuo.",
            href: null,
          },
        },
      ],
    },
    "guerras-senores": {
      paged: true,
      lede: "La muerte de Dong Zhuo no restaura el orden: lo multiplica. Durante dieciséis años los señores se devoran entre sí bajo la bandera del Han que ninguno sirve de verdad. Cao Cao emerge del caos como el único capaz de construir poder duradero. Los demás aprenden, demasiado tarde, lo que significa enfrentarse a él.",
      prose: [
        "La era más larga del Romance es también la más brutal. No hay un frente claro ni un enemigo definido: hay docenas de señores que se alían, traicionan, absorben y destruyen en una cadena que reduce China de veinte potencias a tres en menos de dos décadas. Lü Bu traiciona a Liu Bei. Cao Cao devora a Lü Bu. Yuan Shao aplasta a Liu Bei. Cao Cao aplasta a Yuan Shao. El mapa se redibuja con cada campaña.",
        "Mientras tanto Liu Bei peregrina de señor en señor sin tierra propia, acumulando lealtades personales que no puede convertir en territorio. Su encuentro con Zhuge Liang en Longzhong es el punto de inflexión: por primera vez, el heredero del Han tiene un plan. Por primera vez, su destino tiene forma.",
      ],
      events: [
        {
          y: "196 d.C.",
          type: "Maniobra política",
          n: "Acoger al Hijo del Cielo — La corte en Xu",
          d: "El Emp. Xian lleva años vagando entre señores en guerra. Cao Cao lo escolta y lo instala en Xu. Con el Hijo del Cielo bajo su techo, puede emitir edictos imperiales en nombre del Han. Xun Yu llama a esta decisión la más importante de la era.",
          body: `<p>Tras la muerte de Dong Zhuo, el Emp. Xian queda atrapado entre sus asesinos —Li Jue y Guo Si, los generales norteños que se heredan la tiranía— y un cortejo de señores que simulan rescatarlo mientras calculan cómo usarlo. El Hijo del Cielo pasa años en carros desvencijados entre ejércitos que se disputan su persona como si fuera un sello de validación, no un ser humano. La corte Han es en este período un espectáculo de humillación: ministros que buscan comida entre las ruinas, un Emperador que mendiga en términos velados ante quien quiera escucharle.</p><p>Xun Yu —el más brillante de los consejeros de Cao Cao— ve la oportunidad antes que nadie. Le escribe a Cao Cao con un argumento que no admite réplica: quien acoja al Emperador obtiene la legitimidad de actuar en su nombre. Quien lo deje en manos de otro pierde esa palanca para siempre. La lógica es simple: en el mundo del Han, la forma importa tanto como la fuerza. Un decreto del Emp. Xian firmado en la tienda de Cao Cao vale más que diez victorias militares.</p><p>Cao Cao escolta al Emp. Xian y lo instala en Xu, que rebautiza Xudu —la capital Xu—. A partir de ese momento actúa como primer ministro leal del Han: castiga a quien se opone como traidor al Hijo del Cielo, premia a sus aliados con títulos imperiales y convoca a los señores a rendir homenaje. La mayoría entiende el truco. Ninguno encuentra la manera de desmontarlo.</p><aside class="reader-hist"><strong>Nota histórica</strong>El Sanguo Zhi confirma que Cao Cao trasladó al Emp. Xian a Xu en el primer año de la era Jian'an (196 d.C.). Xun Yu (荀彧) fue el artífice intelectual de la decisión. El Emperador permaneció en Xudu hasta el vigésimo quinto año de Jian'an (220 d.C.), cuando Cao Pi lo obligó a abdicar. Gobernó de nombre durante 31 años.</aside>`,
          char: {
            zh: "荀彧",
            en: "Xun Yu",
            fc: "#1e5abf",
            role: "Consejero supremo de Cao Cao",
            note: "El hombre que diseña la arquitectura política del futuro Wei. Leal al Han de convicción, no por conveniencia —lo que lo llevará a enfrentarse a Cao Cao cuando este reclame el título de Rey de Wei—. La novela le atribuye la estrategia de acoger al Emperador; el Sanguo Zhi lo confirma. Muere en circunstancias que la tradición recoge como un suicidio ante una caja vacía enviada por Cao Cao.",
            href: "assets/Periods/xun-yu.html",
          },
        },
        {
          y: "199 d.C.",
          type: "Caída",
          n: "El fin de Lü Bu en Xiapi 下邳",
          d: "Cao Cao inunda Xiapi desviando dos ríos contra sus murallas. Cuando los propios generales de Lü Bu lo traicionan dormido, el guerrero más temido del Imperio es llevado ante Cao Cao encadenado. Liu Bei decide su suerte con una sola frase.",
          body: `<p>Lü Bu ha ocupado Xuzhou engañando a Liu Bei, ha pactado con Yuan Shu y roto el pacto, ha atacado a Cao Cao y retrocedido, ha asaltado a sus propios aliados y los ha perdido uno a uno. Es el guerrero más temible del Imperio y el político más incapaz: ninguna de sus alianzas sobrevive al año. En 199 d.C. está encerrado en Xiapi con un puñado de generales leales, sin suministros, con el ejército de Cao Cao aplastando el campo.</p><p>Cao Cao decide inundar la ciudad. Sus ingenieros desvían el curso de los ríos Si y Huai y dirigen el agua contra las murallas de Xiapi. La ciudad no cae por asalto: se pudre desde dentro. Los soldados llevan semanas sin dormir. Los generales de Lü Bu —Chen Gong entre ellos, el mismo que huyó con Cao Cao la noche del intento de magnicidio— empiezan a calcular su supervivencia personal.</p><p>La traición llega desde dentro: Hou Cheng, Song Xian y Wei Xu atan a Lü Bu mientras duerme y abren las puertas. Lü Bu es llevado ante Cao Cao en cadenas. La escena que sigue es una de las más amargas de la novela: Lü Bu mira a Liu Bei —que está entre los generales de Cao Cao como aliado coyuntural— y le pide que hable por él. <em>«¿Habéis olvidado cómo os traté en Xuzhou?»</em> Liu Bei mira a Cao Cao y le recuerda en voz baja que Lü Bu ya mató a dos padres adoptivos, Ding Yuan y Dong Zhuo. Cao Cao ordena la ejecución. Lü Bu muere estrangulado. Chen Gong, que se niega a implorar clemencia, es ejecutado después de pedir que Cao Cao cuide de su familia. Cao Cao llora.</p>`,
          char: {
            zh: "呂布",
            en: "Lü Bu",
            fc: "#8b1218",
            role: "El guerrero sin lealtad",
            note: "El arco de Lü Bu es el de la potencia sin dirección: el hombre más peligroso del Imperio en combate singular y el menos fiable en cualquier alianza. Su caída no es derrota militar sino colapso de su propia incapacidad para construir lealtades genuinas. La misma traición que lo elevó —matar a Ding Yuan por Dong Zhuo, matar a Dong Zhuo por Wang Yun— lo destruye cuando sus propios generales lo atan dormido.",
            href: "assets/Periods/lu-bu.html",
          },
        },
        {
          y: "200 d.C.",
          type: "Hazaña",
          n: "Guan Yu — Cinco Pasos, Seis Generales 過五關斬六將",
          d: "Al saber que Liu Bei está con Yuan Shao, Guan Yu abandona el campamento de Cao Cao con las dos cuñadas que protege. Cruza cinco guarniciones sin salvoconducto y mata a seis generales que intentan detenerlo. La lealtad tiene un camino propio.",
          body: `<p>Guan Yu lleva meses sirviendo a Cao Cao por necesidad, no por elección. Las dos esposas de Liu Bei están bajo su protección y no puede abandonarlas sin escolta segura. Cao Cao, que reconoce el valor de Guan Yu y quisiera retenerlo, lo carga de regalos, títulos y atenciones. Guan Yu los acepta con cortesía y no cambia de posición: cuando sepa dónde está Liu Bei, partirá.</p><p>La noticia llega: Liu Bei está en el norte, con Yuan Shao. Guan Yu deja una carta de despedida en el campamento, devuelve los sellos de sus títulos y parte con las dos cuñadas en carros. El problema es que Cao Cao no ha emitido las órdenes de paso. En cada guarnición, el comandante local tiene instrucciones de retener a quien no lleve salvoconducto. Guan Yu no lo lleva.</p><p>El primer paso es Dongling: el comandante Kong Xiu le exige la documentación. Guan Yu lo mata de un golpe. En el paso de Luoyang, Meng Tan y Han Fu salen juntos; Guan Yu mata a Han Fu a la primera carga y a Meng Tan cuando huye. En Qishui, Bian Xi le tiende una trampa en un monasterio: Guan Yu descubre la emboscada y lo decapita. En Xingyang, Wang Zhi prepara un ataque nocturno: Guan Yu lo mata antes del amanecer. En el vado del Río Amarillo, Qin Qi intenta detenerlo con barcas: Guan Yu lo derrota y cruza. Cinco pasos. Seis generales muertos. Las cuñadas de Liu Bei llegan ilesas al norte.</p><aside class="reader-hist"><strong>Nota histórica</strong>El Sanguo Zhi no registra los cinco pasos. Dice únicamente que Guan Yu «abandonó a Cao Cao y fue al encuentro de Liu Bei». La escena es una creación de Luo Guanzhong para ilustrar una verdad del Romance: la lealtad de Guan Yu no es retórica. Cuando tiene que demostrarla, la demuestra contra cualquier obstáculo. Cao Cao, al enterarse, ordena a sus generales que dejen pasar a Guan Yu.</aside>`,
          char: {
            zh: "關羽",
            en: "Guan Yu",
            fc: "#1e8a2e",
            role: "Segundo hermano de Liu Bei",
            note: "Los cinco pasos definen a Guan Yu más que cualquier batalla: elige la lealtad sobre la comodidad, el deber sobre el interés, la palabra dada sobre el salvoconducto. Es el único momento del Romance en que Cao Cao retiene a alguien y luego lo deja marchar por respeto, no por política.",
            href: "assets/Periods/guan-yu.html",
          },
        },
        {
          y: "200 d.C.",
          type: "Batalla decisiva",
          n: "官渡之戰 — La batalla de Guandu",
          d: "Yuan Shao marcha con el mayor ejército del norte. Cao Cao aguanta el cerco en inferioridad numérica durante meses. Un consejero desertor revela dónde están los suministros enemigos. El raid nocturno sobre Wuchao decide el norte de China en una noche.",
          body: `<p>Yuan Shao es en el año 200 el señor más poderoso de China: controla cuatro provincias, tiene el apellido más prestigioso del Han y comanda un ejército de superioridad numérica incontestable. Cao Cao, con el Emp. Xian en Xudu y sus fronteras amenazadas en varios frentes, concentra todo lo que tiene en el vado de Guandu, sobre el río Amarillo, para detener el avance.</p><p>El cerco dura meses. Cao Cao recibe cartas desesperadas de Xun Yu advirtiendo que los suministros se agotan. Yuan Shao, en cambio, tiene depósitos masivos de grano en Wuchao, a pocos kilómetros del frente, custodiados con escasa guardia. La información llega a Cao Cao de la fuente más inesperada: Xu You, consejero de Yuan Shao que este ha insultado y desestimado en un consejo de guerra, cruza las líneas por la noche y se presenta en la tienda de Cao Cao. Le ofrece la localización exacta de Wuchao a cambio de su vida.</p><p>Cao Cao reúne a sus jinetes, los disfraza con uniformes de Yuan Shao y marcha de noche hacia Wuchao. El ataque es rápido y total: los depósitos arden, el comandante Chun Yuqiong es ejecutado, el fuego ilumina el horizonte desde el campamento enemigo. Al amanecer, el ejército de Yuan Shao —que espera el suministro que nunca llega— se desintegra. El señor del norte huye al otro lado del río con ochocientos jinetes. Nunca se recuperará.</p><aside class="reader-hist"><strong>Nota histórica</strong>El Sanguo Zhi confirma la batalla de Guandu (官渡之戰) como el punto de inflexión del norte. Yuan Shao muere en 202 d.C. sin haber consolidado nada. Cao Cao tarda cinco años más en eliminar a sus hijos y completar la unificación del norte.</aside>`,
          char: {
            zh: "曹操",
            en: "Cao Cao",
            fc: "#1e5abf",
            role: "Señor de Wei, Primer Ministro del Han",
            note: "Guandu es la demostración de la tesis Cao Cao: la decisión exacta en el momento exacto vale más que la superioridad de recursos. Mientras Yuan Shao debate en consejo y desestima a sus mejores asesores, Cao Cao actúa sobre información perfecta en una ventana de horas. El norte de China se resuelve en una noche de fuego.",
            href: "assets/Periods/cao-cao.html",
          },
        },
        {
          y: "207 d.C.",
          type: "Encuentro",
          n: "三顾茅庐 — Las Tres Visitas a Longzhong",
          d: "Liu Bei visita tres veces la cabaña de Zhuge Liang en Longzhong. En la tercera visita espera horas junto a la puerta mientras el sabio duerme. Cuando despierta, traza el Plan: tomar Jing, conquistar Yi, esperar el momento. Por primera vez, Liu Bei tiene una estrategia.",
          body: `<p>Liu Bei lleva quince años en movimiento sin territorio propio. Ha servido como vasallo o huésped de Tao Qian, Liu Biao y Yuan Shao, que lo valoran como símbolo del apellido Liu y lo tratan como visita incómoda. Tiene generales leales —Guan Yu, Zhang Fei, Zhao Yun— y no tiene nada donde situarlos. El consejero Xu Shu, antes de ser forzado al servicio de Cao Cao, le habla de un hombre retirado en Longzhong: Zhuge Liang, llamado el Dragón Dormido, que conoce el estado del mundo como si estuviera sobre él.</p><p>Liu Bei va dos veces. Las dos veces Zhuge Liang no está en casa. Sus discípulos le reciben, le ofrecen literatura clásica como sustituto, le dicen que el maestro ha salido sin fecha de regreso. Zhang Fei, en la segunda visita, propone atarlo y traerlo por la fuerza. Liu Bei no responde.</p><p>En la tercera visita, Zhuge Liang está en casa. Duerme. El sirviente propone despertarlo. Liu Bei ordena que no se le moleste y espera de pie junto a la puerta. Espera tanto tiempo que la nieve acumulada en sus hombros se derrite con el calor del interior. Zhuge Liang despierta por sí solo, se estira, murmura unos versos y sale a encontrar a Liu Bei.</p><p>Lo que sigue es el 隆中對 —el Plan de Longzhong—. Zhuge Liang despliega un mapa. Cao Cao tiene el norte y la legitimidad; Sun Quan tiene el sureste y el tiempo. Liu Bei no puede enfrentarse a ninguno en campo abierto. La estrategia es otra: tomar la provincia de Jing —que Liu Biao gobernará sin heredero capaz—, luego conquistar Yi en el oeste, establecer una base doble y esperar la fractura interna del norte para lanzar dos ejércitos simultáneos. Es la primera vez que alguien le traza a Liu Bei no una batalla sino una arquitectura.</p>`,
          char: {
            zh: "諸葛亮",
            en: "Zhuge Liang",
            fc: "#1e8a2e",
            role: "El Dragón Dormido",
            note: "La entrada de Zhuge Liang es el momento de mayor peso dramático del Romance hasta ese punto: un hombre que lo sabe todo esperando a que el hombre correcto llame tres veces. El Plan de Longzhong es la única vez en la novela en que alguien articula la estructura de los tres reinos antes de que existan. Zhuge Liang la dibuja sobre un mapa en 207 d.C. y pasa los siguientes veintisiete años intentando ejecutarla.",
            href: null,
          },
        },
      ],
    },
    "chibi": {
      lede: "Cao Cao ha unificado el norte. Cuando el señor de Jing muere sin resistencia, el camino al sur parece abierto. Pero al sur del Yangtzé, Zhou Yu y Zhuge Liang tejen juntos la trampa de fuego que hará imposible la reunificación durante setenta años.",
      prose: [
        "Chibi es el momento más novelesco del Romance. Los capítulos que la narran son los más celebrados: Zhuge Liang invocando el viento del sureste, la flota de paja que roba flechas, el plan de la cadena de barcos, el fuego que consume al invencible ejército del norte.",
        "Históricamente, Chibi fue una victoria de Zhou Yu sobre un ejército debilitado por la epidemia. La novela la convierte en una obra maestra de ingenio donde cada personaje —Huang Gai, Pang Tong, Lu Su, Zhuge Liang— tiene su papel exacto en la conspiración de la derrota.",
      ],
      events: [
        { y: "208 d.C.", type: "Conquista", n: "Caída de Jingzhou", d: "Liu Biao muere y su sucesor Liu Cong se rinde a Cao Cao sin combatir. Liu Bei huye hacia el sur con cientos de miles de civiles que se niegan a abandonarlo." },
        { y: "208 d.C.", type: "Diplomacia", n: "Zhuge Liang cruza el Yangtzé", d: "Enviado por Liu Bei a la corte de Sun Quan, Zhuge Liang debate con los asesores que aconsejan rendirse. Su elocuencia convence a Sun Quan de resistir. La alianza queda sellada." },
        { y: "208 d.C.", type: "Estratagema", n: "草船借箭 — El barco de paja", d: "Zhuge Liang navega de noche entre la niebla con barcos de paja. Los arqueros de Cao Cao los llenan de flechas. Al amanecer tiene cien mil proyectiles sin haber perdido un hombre." },
        { y: "208 d.C.", type: "Estratagema", n: "连环计 — La Treta de la Cadena", d: "Pang Tong aconseja a Cao Cao encadenar sus barcos para estabilizar la flota. Cao Cao acepta sin saber que firma la condena de su armada al fuego que se acerca." },
        { y: "208 d.C.", type: "Batalla", n: "赤壁之火 — El Gran Fuego de Chibi", d: "Huang Gai conduce barcos incendiados contra la flota encadenada de Cao Cao. El viento del sureste extiende las llamas. La armada norteña arde en horas. El sur de China respira." },
        { y: "208 d.C.", type: "Retirada", n: "La Huida por Hua Rong", d: "Cao Cao huye hacia el norte. Guan Yu lo espera en el paso de Hua Rong y lo deja marchar en recuerdo de favores pasados. La gratitud más tensa del Romance." },
      ],
    },
    "tres-reinos": {
      lede: "China se divide formalmente en tres: Wei en el norte, Shu Han en el suroeste, Wu en el sureste. Un equilibrio armado donde la guerra es perpetua y la paz solo la pausa entre campañas. El trípode dura cuarenta años porque ninguno puede destruir a los otros dos.",
      prose: [
        "La era comienza con la muerte de Cao Cao (220) y la proclamación de Cao Pi como primer Emp. de Wei. Liu Bei responde proclamando Shu Han. Sun Quan espera hasta 229 para coronarse. Tres tronos. Tres legitimidades. Ninguna indiscutible.",
        "El corazón dramático de esta era es Zhuge Liang: el Primer Ministro de Shu dedica once años a cinco expediciones del norte que buscan recuperar el Han. Cada una fracasa por razones distintas. La última lo mata en su campamento de Wuzhang Yuan, mirando hacia Luoyang que nunca alcanzará.",
      ],
      events: [
        { y: "220 d.C.", type: "Fundación", n: "Cao Pi funda Wei 魏", d: "Muerto Cao Cao, su hijo Cao Pi fuerza la abdicación del Emp. Xian y se proclama Emp. de Wei. El Han —de nombre— termina. El norte tiene su nuevo trono imperial." },
        { y: "221 d.C.", type: "Fundación", n: "Liu Bei funda Shu Han 蜀漢", d: "Liu Bei se proclama Emp. en Chengdu reivindicando la legitimidad Han. Zhuge Liang redacta los decretos fundacionales. El suroeste tiene su rey y su misión: restaurar el Han." },
        { y: "221–222 d.C.", type: "Batalla", n: "夷陵之戰 — Batalla de Yiling", d: "Liu Bei marcha contra Wu para vengar la muerte de Guan Yu. Lu Xun lo atrae hacia un terreno forestal y lanza un ataque de fuego. El ejército de Shu es aniquilado. Liu Bei muere al año siguiente." },
        { y: "225 d.C.", type: "Campaña sur", n: "Zhuge Liang y los Siete Capturas de Meng Huo", d: "Zhuge Liang pacifica el sur derrotando siete veces a Meng Huo y liberándolo cada vez. El flanco sur queda asegurado mediante lealtad real, no rendición. Shu puede mirar al norte." },
        { y: "228–234 d.C.", type: "Expediciones", n: "Las Expediciones del Norte", d: "Zhuge Liang lanza cinco campañas contra Wei. Cada una avanza, presiona y retrocede: el flanco fallido de Ma Su en Jieting, la resistencia de Sima Yi, los límites del suministro. Ninguna llega a Luoyang." },
        { y: "234 d.C.", type: "Muerte", n: "Muerte de Zhuge Liang en Wuzhang Yuan", d: "Zhuge Liang muere en su campamento durante la última expedición, mirando al norte que nunca alcanzó. Su figura se convierte en el símbolo literario de la lealtad imposible y la grandeza inútil." },
      ],
    },
    "guerras-ocaso": {
      lede: "Los tres reinos envejecen. Jiang Wei no abandona la obsesión de su maestro y lanza nueve campañas contra Wei que nunca deciden nada. En la sombra, los Sima maniobran para devorar el trono Wei desde dentro. El fin se acerca para el más pequeño de los tres.",
      prose: [
        "Shu Han, el más pequeño, se desangra en campañas ofensivas sin recursos para sostenerlas. El eunuco Huang Hao paraliza los preparativos defensivos cuando el peligro se vuelve real. Cuando Deng Ai cruza Yinping, Chengdu no tiene ejército que defenderla.",
        "Wei, aparentemente el más fuerte, tiene su propio cáncer interno. Sima Yi, Sima Shi y Sima Zhao liquidan uno a uno a los generales que podrían resistirles. El Emp. Cao Mao intenta matar a Sima Zhao con una lanza y muere en la calle. El momento más trágico del ocaso Wei.",
      ],
      events: [
        { y: "238–262 d.C.", type: "Campañas", n: "Las Nueve Campañas de Jiang Wei", d: "Jiang Wei lanza expedición tras expedición buscando el milagro que Zhuge Liang nunca logró. Cada campaña avanza, presiona y retrocede. Los recursos de Shu se agotan sin resultado estratégico." },
        { y: "249 d.C.", type: "Golpe", n: "高平陵政变 — Golpe de Gaoping", d: "Sima Yi aprovecha la ausencia del regente Cao Shuang para tomar Luoyang. Cao Shuang se rinde creyendo promesas de perdón. Es ejecutado al tercer día junto a toda su facción." },
        { y: "260 d.C.", type: "Tragedia", n: "El Emp. Cao Mao sale a matar a Sima Zhao", d: "El joven Emp. Wei, humillado, sale al patio con una lanza al grito de que Sima Zhao traiciona a todos. Un soldado lo atraviesa en la calle. El asesinato de un Hijo del Cielo sin consecuencias." },
        { y: "262–263 d.C.", type: "Invasión", n: "La campaña final contra Shu", d: "Tres columnas Wei invaden Shu. Deng Ai propone cruzar el paso de Yinping por terreno imposible, envolviendo a sus soldados en pieles para descender las montañas. La maniobra más audaz de la era." },
        { y: "263 d.C.", type: "Caída", n: "Caída de Shu Han 蜀漢", d: "Deng Ai emerge al sur de la línea defensiva. Chengdu queda desprotegida. Liu Shan se rinde sin combatir. Jiang Wei intenta un último ardid usando a Zhong Hui contra Sima Zhao. Fracasa y es asesinado." },
      ],
    },
    "sima": {
      lede: "Los Sima replican exactamente lo que los Cao hicieron al Han: el regente devora al rey, el ministro devora al hijo del cielo. Lo que tardó Cao Cao cuarenta años, la familia Sima lo consume en tres generaciones de paciencia calculada y maniobra implacable.",
      prose: [
        "El ascenso de los Sima es la historia más amarga del Romance porque repite el patrón: el sirviente leal se vuelve indispensable, el indispensable se vuelve intocable, el intocable toma el poder. Sima Yi aprendió esta lección observando a los Cao; sus hijos la ejecutaron con brutal eficiencia.",
        "Lo que hace única a esta era es la muerte del Emp. Cao Mao: un joven que sabe que va a morir, que sale de todos modos con una lanza y sus sirvientes, y que muere en la calle como un hombre que prefiere la dignidad al cautiverio dorado. El momento más trágico del ocaso Wei.",
      ],
      events: [
        { y: "249 d.C.", type: "Golpe de Estado", n: "高平陵政变 — Golpe de Gaoping", d: "Sima Yi cierra las puertas de Luoyang mientras Cao Shuang visita una tumba. Cao Shuang cede a cambio de promesas de vida. Es ejecutado al tercer día con toda su facción y los Tres Eminentes." },
        { y: "250–251 d.C.", type: "Consolidación", n: "Sima Yi, señor absoluto de Wei", d: "Con Cao Shuang eliminado, Sima Yi ejerce el poder real. Muere en 251 fingiendo enfermedad hasta el final para despistar a rivales. El aparato que construyó pasa intacto a sus hijos." },
        { y: "254 d.C.", type: "Intriga", n: "Sima Shi depone al Emp. Cao Fang", d: "Cao Fang intenta conspirar contra Sima Shi. Sima Shi actúa antes: el Emp. Wei es depuesto como un sirviente sin méritos y reemplazado por el joven Cao Mao, que heredará la tragedia." },
        { y: "255–257 d.C.", type: "Rebeliones", n: "Últimas rebeliones de los generales Wei", d: "Guanqiu Jian y luego Zhuge Dan levantan sus ejércitos en nombre de los Cao. Sima Shi aplasta el primero; Sima Zhao aplasta el segundo. Cada rebelión liquidada deja a los Sima con más poder y menos rivales." },
        { y: "260 d.C.", type: "Tragedia", n: "El Emp. Cao Mao carga contra Sima Zhao", d: "El joven Emp. Wei sale del palacio armado con una lanza al grito de que Sima Zhao traiciona a todos. Un soldado de Sima Zhao lo atraviesa. El asesinato de un Hijo del Cielo escandaliza, pero no tiene consecuencias." },
        { y: "265 d.C.", type: "Fundación", n: "Sima Yan funda la Dinastía Jin 晉", d: "Sima Yan fuerza la abdicación de Cao Huan, el último Emp. Wei, y se proclama Emp. Wu de Jin. El proyecto de los Cao, que empezó con Cao Cao en 155 d.C., termina en 265." },
      ],
    },
    "jin": {
      lede: "La última pieza cae. Wu, el reino que resistió a Chibi, sobrevivió cincuenta y ocho años de Tres Reinos y aguantó décadas de presión Jin, se rinde ante la armada que desciende el Yangtzé. Sun Hao —el último tirano— llega atado de manos al campamento del vencedor.",
      prose: [
        "La unificación Jin es al mismo tiempo el final del Romance y su epílogo más melancólico. China vuelve a ser una, pero la Dinastía Jin durará menos de cuarenta años antes de desintegrarse en las Guerras de los Ocho Príncipes. El ciclo que comenzó en 184 se cierra en 280, pero ya germina el próximo.",
        "Sun Hao, el último Emp. de Wu, es la figura más patética del cierre: un tirano cruel que agotó la paciencia de sus generales, se rinde atado de manos y llega a Luoyang. Sima Yan lo perdona; Sun Hao responde con insolencia hasta su muerte natural. El último irreductible del mundo que fue.",
      ],
      events: [
        { y: "265 d.C.", type: "Fundación", n: "Sima Yan funda la Dinastía Jin 晉", d: "Sima Yan fuerza la abdicación de Cao Huan, el último Emp. Wei. Se proclama Emp. Wu de Jin con Luoyang como capital. El tercer cambio dinástico en cincuenta años." },
        { y: "265–279 d.C.", type: "Desgaste", n: "Wu se desgasta desde dentro", d: "El Emp. Sun Hao gobierna Wu con crueldad extrema: ejecuta ministros por capricho, agota al ejército con obras suntuarias y pierde la lealtad de los generales que podrían resistir a Jin." },
        { y: "279 d.C.", type: "Invasión", n: "Jin lanza la campaña final", d: "El Emp. Wu de Jin ordena la invasión de Wu por seis frentes simultáneos. Los generales Jin avanzan por el Yangtzé mientras la flota desciende. La resistencia de Wu es fragmentada y sin coordinación." },
        { y: "280 d.C.", type: "Batalla", n: "Wang Jun desciende el Yangtzé", d: "El almirante Wang Jun conduce su armada río abajo destruyendo cadenas de hierro y barreras flotantes. Nanjing queda sin defensa. Sun Hao, incapaz de reunir a sus generales, decide rendirse." },
        { y: "280 d.C.", type: "Rendición", n: "Sun Hao se rinde atado de manos", d: "Siguiendo el ritual de rendición, Sun Hao llega con las manos atadas y un ataúd cargado por sus sirvientes. Sima Yan le corta las ataduras y lo perdona. Wu deja de existir." },
        { y: "280 d.C.", type: "Unificación", n: "China reunificada bajo Jin", d: "Por primera vez desde 189, toda China tiene un solo soberano. El Emp. Wu de Jin celebra el fin del ciclo. Según la leyenda, lloró: sabía que una unificación construida sobre traición dura poco." },
      ],
    },
    "ocho-principes": {
      lede: "Jin había tardado quince años en colapsar. Los Ocho Príncipes —parientes del Emp. Wu concedidos con poderes militares excesivos— comenzaron a devorarse entre sí en 291. Cuando terminaron, China ya no era de nadie. Los Xiongnu entraron por el norte.",
      prose: [
        "La Rebelión de los Ocho Príncipes (291–306 d.C.) es el epílogo más amargo: el Imperio que Zhang Jiao, Dong Zhuo, Cao Cao, Liu Bei, Sun Quan y Sima Yi construyeron y destruyeron durante un siglo se liquida en quince años de guerra fratricida sin un solo protagonista memorable.",
        "Los Xiongnu del norte aprovechan el colapso: invaden las llanuras, saquean Luoyang (311 d.C.) y capturan al Emp. Huai, luego incendian Chang'an (316 d.C.) y capturan al Emp. Min. Jin Occidental termina. El ciclo que comenzó en 184 está cerrado para siempre.",
      ],
      events: [
        { y: "291 d.C.", type: "Crisis dinástica", n: "Estalla la Rebelión de los Ocho Príncipes", d: "Ocho parientes del fundador Jin combaten entre sí por la regencia del Emp. Hui, incapaz de gobernar. Los ejércitos provinciales devoran las provincias mientras la corte sangra sin control." },
        { y: "299–303 d.C.", type: "Escalada", n: "Los Príncipes forman facciones", d: "La rivalidad se multiplica: los Príncipes de Qi, Zhao, Lun, Yong, Chengdu y Donghai forman alianzas cambiantes, se traicionan y se eliminan con ejércitos que ya no sirven al Imperio." },
        { y: "304 d.C.", type: "Amenaza exterior", n: "Los Xiongnu fundan Han Zhao", d: "Liu Yuan, líder Xiongnu con sangre Han, proclama el reino de Han Zhao en el norte. Por primera vez en siglos, una potencia extranjera ocupa territorio chino con vocación de permanencia." },
        { y: "311 d.C.", type: "Catástrofe", n: "Saqueo de Luoyang 洛陽", d: "Los Xiongnu saquean Luoyang y capturan al Emp. Huai. La capital Han original, restaurada por Jin, cae ante bárbaros del norte. El símbolo de China es destruido por segunda vez en un siglo." },
        { y: "316 d.C.", type: "Colapso final", n: "Caída de Chang'an — Fin de Jin Occidental", d: "Chang'an cae ante las fuerzas Xiongnu. El Emp. Min se rinde. La Dinastía Jin Occidental termina. El norte de China entra en el período de los Dieciséis Reinos. El ciclo de 184 está cerrado." },
      ],
    },
  };
  PERIODS.forEach(p => { if (C[p.id]) Object.assign(p, C[p.id]); });
})();
